using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.Json;

namespace AuBtechReviewAgent;

/// <summary>
/// The machine-readable marks that a report was generated by AI, as Article 50(2) of the EU AI Act asks of a system
/// that generates text: meta tags and schema.org data on the report pages, a comment and the PDF document info in
/// main.tex, and a block in the archive's manifest.json. Every mark is written here in code, never by the model, so
/// all outputs of every kind of review say the same thing. The visible disclosure is the AI-use statement, the front
/// page and the author line (<see cref="ArticleInfo.Author"/>); docs/wiki/11-compliance.md describes both.
/// </summary>
public static class AiMarking
{
    public const string Generator = "TraceableAI";

    /// <summary>The keyword every mark carries, so a search for it finds every output.</summary>
    public const string Keyword = "AI-generated";

    /// <summary>The IPTC digital source type for content made by a trained model (schema.org digitalSourceType).</summary>
    public const string DigitalSourceType = "https://schema.org/TrainedAlgorithmicMediaDigitalSource";

    /// <summary>The models, trimmed, empty ones dropped and each named once, in the order given.</summary>
    public static IReadOnlyList<string> Clean(IEnumerable<string?>? models) =>
        (models ?? Array.Empty<string?>())
            .Where(m => !string.IsNullOrWhiteSpace(m))
            .Select(m => m!.Replace('\r', ' ').Replace('\n', ' ').Trim())
            .Distinct(StringComparer.Ordinal).ToList();

    /// <summary>
    /// "TraceableAI 0.5.1 (Department …, Aarhus University) with the language model x": the version only when given, the
    /// models only when any is recorded.
    /// </summary>
    public static string GeneratorLine(IEnumerable<string?>? models, string? version = null)
    {
        var named = Clean(models);
        string with = named.Count switch
        {
            0 => "",
            1 => $" with the language model {named[0]}",
            _ => $" with the language models {string.Join(", ", named)}",
        };
        string v = string.IsNullOrWhiteSpace(version) ? "" : " " + version.Trim();
        return $"{Generator}{v} ({SiteSeo.Organisation}){with}";
    }

    /// <summary>One sentence for a subject or description field: what made the document and that it is AI-generated.</summary>
    public static string Statement(IEnumerable<string?>? models) =>
        $"{Keyword} literature review: written and checked by {GeneratorLine(models)}. It has not been peer reviewed.";

    /// <summary>The meta tags of a report page, as name and content; the page escapes the content.</summary>
    public static IReadOnlyList<(string Name, string Content)> HtmlMeta(IEnumerable<string?>? models, string? version = null)
    {
        var named = Clean(models);
        var tags = new List<(string, string)>
        {
            ("ai-generated", "true"),
            ("generator", GeneratorLine(named, version)),
            ("keywords", Keyword),
        };
        if (named.Count > 0) tags.Add(("ai-models", string.Join(", ", named)));
        return tags;
    }

    /// <summary>
    /// schema.org data for a report page: a Report made by the tool, with the IPTC source type for AI output. It goes in a
    /// script block of type application/ld+json, which is data: the Content-Security-Policy does not run it.
    /// </summary>
    public static string JsonLd(IEnumerable<string?>? models) => JsonSerializer.Serialize(new Dictionary<string, object>
    {
        ["@context"] = "https://schema.org",
        ["@type"] = "Report",
        ["keywords"] = Keyword,
        ["description"] = Statement(models),
        ["digitalSourceType"] = DigitalSourceType,
        ["creator"] = new Dictionary<string, object>
        {
            ["@type"] = "SoftwareApplication", ["name"] = Generator, ["url"] = SiteSeo.RepositoryUrl,
        },
        ["sourceOrganization"] = new Dictionary<string, object> { ["@type"] = "Organization", ["name"] = SiteSeo.Organisation },
    });

    /// <summary>The comment at the top of main.tex: a reader of the source sees at once that the document is AI-generated.</summary>
    public static string LatexComment(IEnumerable<string?>? models)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"% {Keyword}: this document was written and checked by {GeneratorLine(models)}.");
        sb.AppendLine("% The method, counts, figures and references are written in code from the run's files; the prose is model");
        sb.AppendLine("% text whose citations were checked against their sources. It has not been peer reviewed.");
        sb.AppendLine($"% Source code: {SiteSeo.RepositoryUrl}");
        return sb.ToString();
    }

    /// <summary>
    /// hyperref with the PDF's document info: title, author, subject, keywords, creator and producer, so a PDF made from
    /// main.tex says in its properties that it is AI-generated. Links are not boxed or coloured (hidelinks), so the
    /// printed page looks as before. It is loaded last, as hyperref asks. <paramref name="escapedTitle"/> is already LaTeX.
    /// </summary>
    public static string LatexMetadata(string escapedTitle, IEnumerable<string?>? models)
    {
        var named = Clean(models);
        string keywords = string.Join(", ", new[] { Keyword, "literature review", Generator }.Concat(named));
        var sb = new StringBuilder();
        sb.AppendLine(@"\usepackage[hidelinks]{hyperref}");
        sb.AppendLine(@"\hypersetup{");
        sb.AppendLine($"    pdftitle={{{escapedTitle}}},");
        sb.AppendLine($"    pdfauthor={{{Escape(Generator + " (AI system), " + SiteSeo.Organisation)}}},");
        sb.AppendLine($"    pdfsubject={{{Escape(Statement(named))}}},");
        sb.AppendLine($"    pdfkeywords={{{Escape(keywords)}}},");
        sb.AppendLine($"    pdfcreator={{{Escape(GeneratorLine(named))}}},");
        sb.AppendLine($"    pdfproducer={{{Escape(Generator + " (" + Keyword + ") with pdfLaTeX")}}}");
        sb.AppendLine("}");
        return sb.ToString();
    }

    /// <summary>The block in manifest.json: that the archive's report is AI-generated, and by what.</summary>
    public static Dictionary<string, object?> ManifestGenerator(IEnumerable<string?>? models) => new()
    {
        ["Name"] = Generator,
        ["Version"] = RecordingChatCompletionService.AppVersion,
        ["Organisation"] = SiteSeo.Organisation,
        ["Url"] = SiteSeo.RepositoryUrl,
        ["Models"] = Clean(models),
        ["Statement"] = Statement(models),
    };

    // Model names and fixed text in a hyperref key: the characters LaTeX treats specially are escaped.
    private static string Escape(string text)
    {
        var sb = new StringBuilder(text.Length);
        foreach (char c in text)
        {
            sb.Append(c switch
            {
                '\\' => @"\textbackslash{}", '{' => @"\{", '}' => @"\}", '%' => @"\%", '#' => @"\#", '&' => @"\&",
                '_' => @"\_", '$' => @"\$", '~' => @"\textasciitilde{}", '^' => @"\textasciicircum{}",
                _ => c.ToString(),
            });
        }
        return sb.ToString();
    }
}
